#include <bits/stdc++.h>
using namespace std;

constexpr int LIMIT = 100000000;
vector<bool> composite(LIMIT / 2 + 1);

void sieve() {
    for (int i = 3; 1LL * i * i <= LIMIT; i += 2) {
        if (!composite[i / 2]) {
            for (long long j = 1LL * i * i; j <= LIMIT; j += 2LL * i)
                composite[j / 2] = true;
        }
    }
}

bool isPrime(long long n) {
    if (n == 2) return true;
    if (n < 2 || n > LIMIT || n % 2 == 0) return false;
    return !composite[n / 2];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    sieve();

    long long n;
    while (cin >> n) {
        if (isPrime(n))
            cout << "1\n";
        else if (n % 2 == 0 || isPrime(n - 2))
            cout << "2\n";
        else
            cout << "3\n";
    }

    return 0;
}

